mapper.select:
select distinct ee.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId/*资产代码*/, fp.FINPROD_ABBR finprodAbbr/*资产简称*/, fp.COUPON_SPECIES couponSpecies/*息票品种*/, fp.TRADE_MARKET tradeMarket/*交易场所*/, fp.REGIST_ORG registOrg, #{loginUserId} ourTrader/*本方交易员*/, ee.COUNTER_ID counterId/*交易对手*/, MCP.COUNTER_NAME counterName/*交易对手*/, fpi.TENDER_TARGET tenderTarget/*招标标的*/, fp.CCY ccy /*币种*/, CASE WHEN fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND fpi.TENDER_TYPE IN (#{TENDER_TYPE_01}, #{TENDER_TYPE_02}) THEN fpi.ISSUE_DATE WHEN (fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN (#{TENDER_TYPE_03}, #{TENDER_TYPE_04}))) OR fpi.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN fpi.TENDER_SDATE END AS bidDateStart/*投标日 开始*/, CASE WHEN fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND fpi.TENDER_TYPE IN (#{TENDER_TYPE_01}, #{TENDER_TYPE_02}) THEN fpi.ISSUE_DATE WHEN (fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN (#{TENDER_TYPE_03}, #{TENDER_TYPE_04}))) OR fpi.ISSUE_CLASS = #{ISSUE_CLASS_03} THEN fpi.TENDER_SDATE END AS bidDateEnd/*投标日 结束*/, fpi.PAY_EDATE payEdate/*缴款截止日*/, fpi.PAY_DATE payDate/*缴款日*/, fpi.ASSIGN_REGDATE assignRegdate/*债权债务登记日*/, CASE WHEN fp.CIRCULATION_DATE IS NOT NULL THEN fp.CIRCULATION_DATE ELSE fpa.LISTING_DATE end AS listingDate/*上市日*/, fp.CIRCULATION_DATE circulationDate /*上市流通日*/, CASE WHEN ( fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND fpi.TENDER_TYPE IN (#{TENDER_TYPE_01}, #{TENDER_TYPE_02}) AND fpi.ISSUE_DATE < TO_DATE(#{sysDate,jdbcType=VARCHAR},'YYYY-MM-DD') ) OR (((fpi.ISSUE_CLASS = #{ISSUE_CLASS_02} AND (fpi.TENDER_TYPE IS NULL OR fpi.TENDER_TYPE IN (#{TENDER_TYPE_03}, #{TENDER_TYPE_04})) ) OR fpi.ISSUE_CLASS = #{ISSUE_CLASS_03} ) AND fpi.TENDER_EDATE < TO_DATE(#{sysDate,jdbcType=VARCHAR},'YYYY-MM-DD') ) THEN #{WIN_TYPE_03} ELSE #{WIN_TYPE_01} END AS biddingMethod/*投标方式*/, ee.ENTRUST_ID/*指令代码*/, eed.PORTFOLIO_ID, pp.PORTFOLIO_NAME/*组合名称*/, eed.ACCT_NO/*资金账户*/, eebp.BID_PRICE/*投标标位*/, eed.INV_AIM/*业务模式*/, eed.SEC_ACCT_ID/*证券账户*/, ssai.SEC_ACCT_NAME/*证券账户*/, ee.INV_MANAGER_ID/*投资经理ID*/, SU.REAL_NAME INV_MANAGER_NAME/*投资经理*/, eed.ENTRUST_NUM*100 ENTRUST_NUM /*委托券面总额*/, eed.ENTRUST_NUM*100 avaNum /*剩余券面总额*/, eebp.BID_PRIN_AMT*100 BID_PRIN_AMT /*委托投标券面*/ from ETR_ENTRUST ee left join ETR_ENTRUST_DETAIL eed on ee.ENTRUST_ID = eed.ENTRUST_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = eed.PORTFOLIO_ID left join ETR_ENTRUST_BID_PRICE eebp on eebp.ENTRUST_ID = ee.ENTRUST_ID and eed.PORTFOLIO_ID = eebp.PORTFOLIO_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.FINPROD_ID left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID = ee.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = ee.FINPROD_ID LEFT JOIN SYS_USER SU ON ee.INV_MANAGER_ID = SU.USER_NAME LEFT JOIN STL_SEC_ACCT_INFO ssai ON eed.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN MST_COUNTER_PARTY MCP ON ee.COUNTER_ID = MCP.COUNTER_ID
ee.ENTRUST_ID in
#{item}

